/* Shared duration styling in model settings and shot controls. */
label:has(>[data-video-seconds]),label:has(>[data-setting="max_clip_seconds"]),label:has(>[data-seconds]){color:#d1cbe7;font-size:12px;font-weight:400;line-height:1.5;gap:7px}
input:is([data-video-seconds],[data-setting="max_clip_seconds"],[data-seconds]){color:#edf2ec;background:#1b1839;border:1px solid #51496f;border-radius:6px;padding:10px 12px;font-size:12px;min-height:36px}

/* Opt-in glass surfaces. No dimensions or media pixels are changed. */
html[data-ecco-theme="ocean"]{color-scheme:light;--glass-backdrop:radial-gradient(ellipse at 15% 8%,#ffffffba,transparent 48%),radial-gradient(ellipse at 90% 55%,#64b4d255,transparent 50%),linear-gradient(175deg,#cbe6f7 0%,#edf6fa 38%,#a8d4e4 56%,#eee3ce 100%);--glass-solid:#eef6fa;--glass-highlight:#ffffff88;--glass-shadow:#214b6920}
html[data-ecco-theme="dark-sky"]{color-scheme:dark;--glass-backdrop:radial-gradient(ellipse at 8% 24%,#18558999,transparent 50%),radial-gradient(ellipse at 80% 8%,#17558677,transparent 45%),linear-gradient(145deg,#061c32,#020e1b);--glass-solid:#102c48;--glass-highlight:#99d5ff30;--glass-shadow:#00081455}
html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]){background:var(--glass-backdrop) fixed;color:var(--ecco-theme-text)}
html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]) :is(body,main,#page,#workspace-entry,#story-choice-screen){background:transparent!important}
html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]) :is(body>aside,main>header,.panel,.card,.generation-form,dialog,.workspace-menu-items,#workspace-billing-drawer,#workspace-usage-drawer,#workspace-theme-drawer,#connection-indicators,#workspace-community-controls,#workspace-settings-controls,.library-control-panel,.gpu-card,.model-card){background:var(--ecco-theme-surface)!important;border-color:var(--ecco-theme-border)!important;box-shadow:inset 0 1px 0 var(--glass-highlight),0 10px 30px var(--glass-shadow);-webkit-backdrop-filter:blur(16px) saturate(115%);backdrop-filter:blur(16px) saturate(115%);color:var(--ecco-theme-text)}
html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]) :is(input,textarea,select){background:var(--ecco-theme-control)!important;color:var(--ecco-theme-text)!important;border-color:var(--ecco-theme-border)!important}
html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]) :is(select option,select optgroup){background:var(--glass-solid);color:var(--ecco-theme-text)}
html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]) button{background:var(--ecco-theme-control)!important;color:var(--ecco-theme-text)!important;box-shadow:inset 0 0 0 1px var(--ecco-theme-border)}
html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]) :is(button:hover,button.active,[aria-selected="true"],.theme-preset-option:has(input:checked)){color:var(--ecco-theme-accent)!important;box-shadow:inset 0 0 0 1px var(--ecco-theme-accent)}
html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]) :is(button,input,textarea,select,summary,a):focus-visible{outline:2px solid var(--ecco-theme-accent)!important;outline-offset:3px}
html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]) :is(.entry-copyright,.entry-subtitle){color:var(--ecco-theme-muted)!important}
html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]) dialog::backdrop{background:#071f3744;backdrop-filter:blur(3px)}
@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]){--ecco-theme-surface:var(--glass-solid)!important;--ecco-theme-control:var(--glass-solid)!important}}
@media(prefers-reduced-transparency:reduce){html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]){--ecco-theme-surface:var(--glass-solid)!important;--ecco-theme-control:var(--glass-solid)!important}html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]) *{backdrop-filter:none!important;-webkit-backdrop-filter:none!important}}
/* Backdrop filters create stacking contexts: keep the ribbon above page controls. */
html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]) main>header{position:relative;z-index:30}
html:is([data-ecco-theme="ocean"],[data-ecco-theme="dark-sky"]) [data-category="Activity"]>.workspace-menu-items{right:30px}

