/* Ecco logo palette */
.logo{width:62px;height:62px;object-fit:contain;border-radius:14px;background:#211e46}.brand{gap:10px}.badge{color:#21d4ef;border-color:#327d91}.side-bottom li.done{color:#47df44}nav button.active{box-shadow:inset 3px 0 #ffdc24}nav button:nth-child(2).active{box-shadow:inset 3px 0 #ff80cf}nav button:nth-child(3).active{box-shadow:inset 3px 0 #21d4ef}label{color:#d1cbe7}.header-right{flex-wrap:wrap;justify-content:flex-end}.models-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.model-panel{border-top:3px solid var(--border);box-shadow:none}.model-panel.is-active{border-top-color:var(--accent);box-shadow:0 0 0 1px rgba(255,220,36,.18),0 0 14px rgba(255,220,36,.12)}.model-fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.model-fields .wide{grid-column:1/-1}.model-status{min-height:36px}.model-summary{border-left:3px solid #21d4ef;padding:10px 14px;background:#1b1839}.model-status.pending{color:#ffcb77}button:focus-visible,a:focus-visible{outline:2px solid #21d4ef;outline-offset:3px}@media(max-width:900px){.models-grid{grid-template-columns:1fr}}

.brand{font-size:20px;letter-spacing:-.4px;white-space:nowrap;gap:8px}.logo{width:46px;height:46px;flex-shrink:0}.brand span:not(.logo){font-size:8px;letter-spacing:1.2px}

.model-nav{display:grid;gap:12px;padding:18px 0;border-top:1px solid #28364f;margin-top:14px}.model-nav h2{font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:#8b9bb4;margin:0}.model-nav label{display:grid;gap:7px;font-size:12px;color:#dae3f3}.model-nav select{width:100%;min-width:0;background:#131e32;color:#edf3ff;border:1px solid #35445f;border-radius:8px;padding:9px 7px;font-size:12px}.model-nav small{color:#8b9bb4;font-size:11px;line-height:1.5}.model-nav select:focus-visible{outline:2px solid #f5cb40;outline-offset:2px}.model-nav .secondary{font-size:12px}aside{overflow-y:auto}

.activity>summary{cursor:pointer;font-weight:600;padding:14px 0}.generation-spinner{display:inline-block;width:16px;height:16px;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:generation-spin .8s linear infinite;vertical-align:middle;margin-right:9px}button[aria-busy="true"]{opacity:.85;cursor:wait}@keyframes generation-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.generation-spinner{animation-duration:2s}}

.activity-drawer{position:fixed;z-index:90;right:0;top:0;bottom:0;width:min(520px,95vw);padding:24px;background:#102b32;box-shadow:-12px 0 40px #0008;overflow:auto;border-left:1px solid #417078}.activity-drawer[hidden]{display:none}.activity-drawer .job{display:block;padding:16px 0}.activity-drawer .job>div{margin-bottom:6px}.refine-preview{width:160px;max-height:120px;object-fit:contain;border-radius:8px}.subject-row{border-top:1px solid #47717a;padding:12px 0;display:grid;gap:8px}.shot-subjects{grid-column:1/-1}

/* GPU entry-point selector */
.gpu-picker{max-width:1000px;margin:20px auto;padding:30px}.gpu-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;margin:28px 0}.gpu-card{padding:26px;border:1px solid #4b4766;border-radius:16px;background:#25213f;display:flex;flex-direction:column;gap:14px}.gpu-card h3{font-size:32px;margin:0}.gpu-card p{margin:0}.gpu-card .gpu-detail{min-height:58px}.gpu-card .gpu-open{margin-top:auto}.gpu-status{font-weight:600;color:#d3cbeb}.gpu-card[data-status=ready],.gpu-card[data-status=running]{border-color:#36c4aa}.gpu-card[data-status=ready] .gpu-status,.gpu-card[data-status=running] .gpu-status{color:#66e3c9}.gpu-card[data-status=unknown] .gpu-status{color:#e9c97f}@media(max-width:700px){.gpu-grid{grid-template-columns:1fr}.gpu-picker{padding:20px}.gpu-picker .section-head{flex-wrap:wrap;gap:16px}}

/* Match Billing's side-sliding panel; presets affect colors only. */
[data-category="Activity"] .workspace-menu-items{overflow:visible}
#workspace-theme-drawer{display:flex!important;position:absolute;left:100%;top:0;width:100%;min-height:100%;border:1px solid var(--ecco-theme-border,#48405c);border-radius:9px;box-shadow:0 12px 32px #0006;box-sizing:border-box;padding:12px;flex-direction:column;justify-content:center;gap:10px;background:var(--ecco-theme-surface,var(--panel,#252039));z-index:2;visibility:visible;clip-path:inset(0 0 0 0);transition:clip-path .2s ease,visibility .2s}
#workspace-theme-drawer[hidden]{clip-path:inset(0 100% 0 0);visibility:hidden;pointer-events:none}
#workspace-theme-drawer .theme-preset-option{display:flex;flex-direction:row;align-items:center;gap:10px;cursor:pointer;margin:0;color:var(--ecco-theme-text,#fff)}
#workspace-theme-drawer .theme-preset-option:has(input:checked){color:var(--accent,#ffdc24)}
#workspace-theme-drawer input{width:auto;margin:0;accent-color:var(--accent,#ffdc24)}
@media(prefers-reduced-motion:reduce){#workspace-theme-drawer{transition:none}}

/* Shared menu surfaces and independent connection-state colors. */
.workspace-menu>.workspace-menu-items,#workspace-billing-drawer,#workspace-theme-drawer{background-color:var(--ecco-theme-surface,var(--panel,#252039))!important;border-color:var(--ecco-theme-border,#48405c)!important}
#workspace-billing-drawer p{color:var(--ecco-theme-text,#fff)!important}
#connection-indicators{background:linear-gradient(180deg,var(--ecco-theme-control,#302a43),var(--ecco-theme-surface,#242031));border-color:var(--ecco-theme-border,rgba(190,180,215,.22))}
#connection-indicators #studio-ai-button,#connection-indicators #studio-storage-indicator,#connection-indicators #connected-accelerator{color:var(--ecco-theme-disconnected,#fff)!important}
#connection-indicators #studio-ai-button[data-connected=true],#connection-indicators #studio-storage-indicator[data-connected=true],#connection-indicators #connected-accelerator.accelerator-connected{color:var(--ecco-theme-connected,#ffdc24)!important}

/* Keep status text readable without fading the entire button. */
#gpu-picker-dialog .gpu-card .gpu-open{color:var(--ecco-theme-disconnected,#fff)!important;opacity:1!important;filter:none!important}
#gpu-picker-dialog .gpu-card:is([data-status="unknown"],[data-status="unchecked"],[data-status="running"]) .gpu-open{color:color-mix(in srgb,var(--ecco-theme-disconnected,#fff) 55%,transparent)!important}
#gpu-picker-dialog .gpu-card .gpu-open[data-connected="true"]{color:var(--ecco-theme-connected,#ffdc24)!important}

/* Generation panels must resolve the active theme before legacy fallbacks. */
#page .generation-form{background:var(--ecco-theme-surface,var(--panel,#24203e))!important;color:var(--ecco-theme-text,inherit)}
#page .generation-form .generation-section{border-color:var(--ecco-theme-border,#51496f)}

/* Sidebar rows stay unboxed in every palette, including glass themes.
   Keep selection in the text/markers and reserve outlines for keyboard focus. */
html body>aside :is(#workspace-library-group,#workspace-production-group,nav) :is(button,summary),
html body>aside>#workspace-trash{
 background:transparent!important;border:0!important;box-shadow:none!important;
}
html body>aside :is(#workspace-library-group,#workspace-production-group,nav) :is(button,summary):is(:hover,:focus,:active,.active,.selected,[aria-selected="true"],[aria-pressed="true"]),
html body>aside>#workspace-trash:is(:hover,:focus,:active){
 background:transparent!important;border:0!important;box-shadow:none!important;
 color:var(--ecco-theme-accent,var(--accent,#ffdc24))!important;
}
html body>aside :is(#workspace-library-group,#workspace-production-group,nav) :is(button,summary):focus-visible,
html body>aside>#workspace-trash:focus-visible{
 outline:2px solid var(--ecco-theme-accent,var(--accent,#ffdc24))!important;outline-offset:3px;
