#ecco-activity-tabs{margin:14px 0;gap:8px}#ecco-debug-view{overflow-wrap:anywhere}#ecco-debug-view[hidden],#jobs[hidden]{display:none!important}#ecco-debug-view select,#ecco-debug-view textarea{width:100%;box-sizing:border-box}#ecco-debug-view .debug-image{display:block;max-width:100%;max-height:240px;object-fit:contain;border-radius:8px}#ecco-debug-view figure{margin:10px 0}#ecco-debug-view figcaption{font-size:11px;color:#b8b0cd}.debug-facts{display:grid;grid-template-columns:85px 1fr;gap:8px;font-size:12px}.debug-facts dd{margin:0}.debug-facts dt{color:#b8b0cd}#ecco-debug-view pre{white-space:pre-wrap;font-size:11px}#ecco-debug-view h3{font-size:14px;margin:18px 0 8px}.debug-error{color:var(--accent,#ffdc24)}

/* Consistent yellow for open menus, selected navigation and icon actions. */
#workspace-menus .workspace-menu[open]>summary,#workspace-menus .workspace-menu>summary:active,#workspace-menus .workspace-menu>summary:focus-visible,#workspace-menus .workspace-menu-items>button:focus,#workspace-menus .workspace-menu-items>a:focus,nav button.active,.workspace-library .tree-folder.selected,.workspace-library[open]>summary,.workspace-library[open]>summary .library-symbol::before,.asset-icon:active,.asset-icon:focus-visible,#workspace-trash{color:var(--accent,#ffdc24)!important}
#workspace-trash svg{stroke:currentColor}

.tree-image{display:flex!important;align-items:center;gap:8px}.tree-image img{width:40px;height:40px;object-fit:cover;border-radius:5px;flex-shrink:0}.tree-image span{overflow:hidden;text-overflow:ellipsis}.card.library-highlight{outline:2px solid var(--accent,#ffdc24);outline-offset:3px}

.library-view-label{display:flex;align-items:center;gap:8px;font-size:12px}.library-view-label select{width:auto;min-width:125px}#library-gallery.library-view-small{display:grid;grid-template-columns:repeat(auto-fill,minmax(165px,1fr));gap:12px}#library-gallery.library-view-large{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:18px}#library-gallery.library-view-list{display:flex;flex-direction:column;gap:8px}#library-gallery.library-view-small .card>img{height:120px;width:100%;object-fit:contain}#library-gallery.library-view-large .card>img{height:280px;width:100%;object-fit:contain}#library-gallery.library-view-list .card{display:grid;grid-template-columns:80px minmax(0,1fr);align-items:center;min-height:85px;padding:8px;position:relative}#library-gallery.library-view-list .card>img{width:72px;height:72px;object-fit:contain}#library-gallery.library-view-list .card-body{padding:4px 70px 4px 12px}#library-gallery.library-view-small .card-body{padding:10px;font-size:12px}#library-gallery.library-view-list .card-body>.help,#library-gallery.library-view-small .card-body>.help{display:none}#library-gallery .library-card-actions>summary{cursor:pointer;color:var(--accent,#ffdc24);font-size:12px;margin-top:8px}#library-gallery .library-card-actions:not([open])>.actions{display:none}#library-gallery.library-view-large .library-card-actions>.actions{display:flex}#library-gallery.library-view-large .library-card-actions>summary{display:none}

#ecco-debug-view textarea[aria-label="Submitted prompt"]{font-size:12px!important;line-height:1.45!important;font-family:ui-monospace,SFMono-Regular,Consolas,monospace!important;height:160px;min-height:100px;max-height:280px;overflow:auto;resize:vertical;padding:10px}#ecco-debug-view pre{font-size:11px;line-height:1.4;max-height:200px;overflow:auto}

.project>.workspace-library:not([open])>summary,.project>.workspace-library:not([open])>summary>span:not(.library-symbol){color:#fff!important}.project>.workspace-library[open]>summary>span:not(.library-symbol){color:var(--accent,#ffdc24)!important}

#workspace-copyright,#workspace-entry .entry-copyright{color:var(--accent,#ffdc24)!important}

#workspace-trash,#workspace-copyright,#workspace-entry .entry-copyright{color:#fff!important}

/* Activity drawer uses the navigation palette and compact controls. */
#activity-panel{background:#201d44;color:#eeebf5;border-left:1px solid #45405e;padding:20px}
#activity-panel button{width:auto;min-width:0;min-height:30px;padding:6px 10px;font-size:12px;line-height:1.4;flex:0 0 auto}
#activity-panel #ecco-activity-tabs{display:flex;justify-content:flex-start;gap:8px;margin:12px 0}
#activity-panel #ecco-activity-tabs button{flex:0 0 auto;width:auto}
#activity-panel #close-activity{width:30px;height:30px;padding:0;font-size:18px}

/* Six-step story creation journey. */
#workspace-production-group.story-journey{margin-top:20px}
.story-journey>h2{font-size:14px;font-weight:600;margin:0 0 10px;padding:0 10px;color:var(--text,#eeebf5)}
.story-journey>.workspace-library-content{padding:0;border:0}
#workspace-production-group .journey-step{display:block;width:100%;text-align:left;font-size:12px;line-height:1.5;padding:9px 10px;border-radius:6px;margin:3px 0;background:transparent;color:var(--muted,#b8b4c5)}
#workspace-production-group .journey-step.active{background:var(--accent,#ffdc24);color:#191720}
#journey-guide{display:flex;justify-content:space-between;align-items:center;gap:18px;border-bottom:1px solid #ffffff18;padding:4px 0 18px;margin-bottom:20px}
#journey-guide[hidden]{display:none}
#journey-guide small{font-size:10px;letter-spacing:.12em;color:var(--accent,#ffdc24)}
#journey-guide h2{font-size:20px;margin:5px 0}
#journey-guide p{font-size:12px;line-height:1.6;color:var(--muted,#b8b4c5);margin:0;max-width:620px}
.journey-actions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}
.journey-actions button{font-size:12px;padding:7px 10px}
@media(max-width:800px){#journey-guide{align-items:flex-start;flex-direction:column}.journey-actions{justify-content:flex-start}}

/* Library creation controls use the same compact type as label rows. */
#workspace-library-group .tree-create{font-size:12px!important;font-weight:400!important;line-height:1.5!important;padding:7px 10px!important;min-height:0!important}
#workspace-library-group .tree-create :is(span,i,svg){font-size:inherit!important;width:1em;height:1em}
#workspace-library-group .tree-create::before,#workspace-library-group .tree-create::after{font-size:inherit!important}

#page .section-head .row>button,#page .library-view-label,#page .library-view-label select{font-size:12px!important;font-weight:400!important;min-height:30px;padding:6px 10px!important;width:auto}

/* Shared compact button sizing across Studios menus and action toolbars. */
body:not(.workspace-entry-mode) :is(#workspace-menus button,#workspace-menus .workspace-menu>summary,#workspace-library-group button,#workspace-production-group button,main button,dialog button:not(.pdf-text-control)){
 font-size:12px!important;line-height:18px!important;font-weight:500!important;min-height:32px!important;padding:6px 10px!important;box-sizing:border-box;
}
body:not(.workspace-entry-mode) :is(.asset-icon,.workspace-delete,.storage-key-toggle,.tree-branch-toggle){width:32px!important;min-width:32px!important;height:32px!important;padding:6px!important}
body:not(.workspace-entry-mode) :is(.asset-icon,.workspace-delete,.storage-key-toggle) svg{width:16px!important;height:16px!important}
#workspace-menus .workspace-menu>summary{display:flex;align-items:center}

